#!/usr/bin/env node
// Feature 029: collect every *placed* Gemini Notebook Studio artifact into static/studio-index.json,
// which the topic page's Studio panel fetches at runtime (same convention as content-index.json:
// generated by prestart/prebuild, gitignored, not a source of truth).
//
// Shape: { "<course>/<unit>/<topic>": { "en": [item...], "ur": [item...] } }
// item = { kind, part?, title, audience, alt, src?, url? }   (src = site path of a text asset)
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { findManifests } from './check-studio-manifest.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');

export function buildStudioIndex(manifests) {
  const index = {};
  for (const m of manifests) {
    for (const a of m.artifacts) {
      if (a.status !== 'placed') continue;
      const key = `${m.course}/${m.unit}/${a.topic}`;
      const slot = (index[key] ??= { en: [], ur: [] });
      slot[a.locale].push({
        kind: a.kind,
        ...(a.part ? { part: a.part } : {}),
        title: a.title,
        audience: a.audience ?? 'all',
        alt: a.alt ?? '',
        ...(a.asset_path ? { src: a.asset_path } : {}),
        ...(a.host_url ? { url: a.host_url } : {}),
      });
    }
  }
  for (const slot of Object.values(index)) {
    for (const loc of ['en', 'ur']) slot[loc].sort((x, y) => x.kind.localeCompare(y.kind) || (x.part ?? 0) - (y.part ?? 0));
  }
  return index;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const manifests = findManifests(ROOT).map((f) => JSON.parse(readFileSync(f, 'utf8')));
  const index = buildStudioIndex(manifests);
  mkdirSync(join(ROOT, 'static'), { recursive: true });
  writeFileSync(join(ROOT, 'static', 'studio-index.json'), `${JSON.stringify(index)}\n`);
  console.log(`build-studio-index: ${Object.keys(index).length} topic(s) with placed Studio items`);
}
